const envelope = $input.first().json;
const input = envelope.body ?? envelope;
const requestId = envelope.headers?.['x-request-id'] ?? String($execution.id);
const requiredFields = ["leadId","company","email","region"];
const missingFields = requiredFields.filter((field) => input[field] === undefined || input[field] === null || input[field] === '');

if (missingFields.length > 0) {
  return [{
    json: {
      ok: false,
      httpStatus: 400,
      requestId,
      error: 'validation_error',
      message: 'Required fields are missing',
      details: { missingFields },
      requiredFields
    }
  }];
}

const rules = [
  {
    "field": "targetAccount",
    "operator": "truthy",
    "points": 35,
    "reason": "Company is a named target account"
  },
  {
    "field": "employeeCount",
    "operator": "gte",
    "value": 1000,
    "points": 25,
    "reason": "Enterprise employee threshold met"
  },
  {
    "field": "highIntent",
    "operator": "truthy",
    "points": 25,
    "reason": "High-intent behavior detected"
  },
  {
    "field": "requestedDemo",
    "operator": "truthy",
    "points": 25,
    "reason": "Buyer requested a demonstration"
  },
  {
    "field": "marketingConsent",
    "operator": "falsy",
    "points": -40,
    "reason": "Marketing consent is not present"
  }
];

function matches(rule, value) {
  switch (rule.operator) {
    case 'missing': return value === undefined || value === null || value === '';
    case 'truthy': return value === true;
    case 'falsy': return value !== true;
    case 'equals': return value === rule.value;
    case 'includes': return Array.isArray(value) && value.includes(rule.value);
    case 'gt': return Number(value) > Number(rule.value);
    case 'gte': return Number(value) >= Number(rule.value);
    case 'lt': return Number(value) < Number(rule.value);
    default: return false;
  }
}

const matchedRules = rules
  .filter((rule) => matches(rule, input[rule.field]))
  .map(({ field, points, reason }) => ({ field, points, reason }));
const score = Math.max(0, Math.min(100, matchedRules.reduce((total, rule) => total + rule.points, 0)));
const priorityBand = score >= 70 ? 'high' : score >= 30 ? 'medium' : 'low';
const decisions = {"low":"route_to_nurture_or_review","medium":"assign_sdr_queue","high":"assign_enterprise_owner"};

return [{
  json: {
    ok: true,
    httpStatus: 200,
    requestId,
    workflow: 'enterprise-lead-routing',
    decision: decisions[priorityBand],
    priorityBand,
    score,
    matchedRules,
    recommendedActions: ["Upsert the lead in CRM","Apply regional ownership rules","Start an SLA timer for qualified handoff"],
    evaluatedAt: new Date().toISOString()
  }
}];
